-- REQ-262 (levels phase 2, part 3; Nick 2026-11-12): beginner lesson variants,
-- BUILT BUT SWITCHED OFF. Nothing here turns a course on and nothing is
-- generated by this migration.
--
-- 1. lesson_content_variants: a second version of a lesson for learners at
--    level 'new' (design section 5; `level` allows only 'new', because an
--    Experienced version is a display choice made from the standard cards).
--    The same content columns as lesson_content (the lesson_content_overrides
--    pattern) plus:
--      teach_steps          Teach in 3 to 5 small steps, each with its quick
--                           check (plain explanation, one everyday example, the
--                           precise term, one multiple-choice check with a
--                           reason for every option)
--      source_lesson_hash   sha256 of the standard shared lesson this was
--                           written from. When the standard lesson changes the
--                           hash no longer matches and the variant is NOT
--                           served (lib/lesson-variant.ts): a stale beginner
--                           version never contradicts a corrected standard one
--      consistency          what the consistency check (a second model reads
--                           the beginner steps against the standard Teach)
--                           said: { consistent, contradictions }
--    The Solo check is the standard Solo check, copied byte for byte, so the
--    bar and the key are the same at every level; only the Guided item may
--    differ. teach and teach_cards are copied from the standard lesson (the
--    worked example card still follows the steps).
--    A learner who never reaches this table goes through today's code.
-- 2. subject_tracks.beginner_variants: the per-course switch, default false.
--    NO course is turned on here or by the seed. Clinical courses never get
--    beginner versions: lib/lesson-variant.ts refuses them whatever this flag
--    says, and generation refuses them too (lib/beginner-variants.ts).
-- 3. attempts.lesson_variant: which version of the lesson a Guided or Solo
--    answer was given to ('new'; null is the standard lesson, so every
--    existing row reads as standard). Grading, the hint reveal and a problem
--    report use the key of the version answered (lib/lesson-variant.ts).
-- 4. item_holdbacks_item_kind_067 restated under the same name with
--    'lesson_variant' added (a variant held back for accuracy is logged like
--    a lesson or a primer), as 079 did for 'primer' (FAIL-1720).
--
-- Every row in lesson_content_variants is shared content with no learner
-- column; it is deleted with its objective (on delete cascade).
--
-- ORDER. Apply BEFORE the backend that reads it: the lesson route, the grade
-- route and the hint route resolve a lesson through lib/lesson-variant.ts,
-- which reads subject_tracks.beginner_variants and lesson_content_variants,
-- and the grade route writes attempts.lesson_variant. /api/health probes
-- them (lib/schema-status.ts). The code before this migration never reads
-- any of it.
--
-- LOCKING. One new table; one column with a constant default on
-- subject_tracks and one nullable column without a default on attempts
-- (catalog-only changes, no rewrite, but ACCESS EXCLUSIVE each); the
-- attempts check is added NOT VALID (no scan: every existing row is null by
-- construction, the column being new), as 062 did for attempts_simtask_shape;
-- a quiet moment can run `alter table attempts validate constraint
-- attempts_lesson_variant_083`. item_holdbacks' check is swapped NOT VALID
-- then validated (a small log table). The migration tool runs the file in ONE
-- transaction, so the locks are held to commit; lock_timeout 5 s as usual: a
-- busy moment fails the migration cleanly (nothing applied, re-run it).
--
-- ROLLBACK (deploy the earlier backend first):
--   drop table if exists lesson_content_variants;
--   alter table attempts drop constraint if exists attempts_lesson_variant_083;
--   alter table attempts drop column if exists lesson_variant;
--   alter table subject_tracks drop column if exists beginner_variants;
--   delete from item_holdbacks where item_kind = 'lesson_variant';
--   -- then restate item_holdbacks_item_kind_067 without 'lesson_variant' (079's list).
-- Attempts answered to a variant lose the marker; their answers stay.
--
-- Safe to run twice: if not exists, guarded DO blocks.

set local lock_timeout = '5s';

-- 1. lesson_content_variants -------------------------------------------------------

create table if not exists lesson_content_variants (
    objective_id uuid not null references objectives(id) on delete cascade,
    level text not null check (level in ('new')),
    guess_prompt text not null,
    teach text not null,
    fade_problem text not null,
    fade_choices jsonb not null,              -- string[4]
    fade_correct_index int not null,
    fade_why text not null,
    solo_check text not null,
    solo_choices jsonb not null,
    solo_correct_index int not null,
    solo_why text not null,
    fade_option_reasons jsonb,
    solo_option_reasons jsonb,
    teach_cards jsonb,
    teach_steps jsonb not null,
    source_lesson_hash varchar(64) not null,
    consistency jsonb,
    model varchar(100) not null,
    generated_at timestamptz not null default now(),
    primary key (objective_id, level)
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'lesson_content_variants_steps_083') then
    alter table lesson_content_variants add constraint lesson_content_variants_steps_083
      check (jsonb_typeof(teach_steps) = 'array' and jsonb_array_length(teach_steps) between 3 and 5);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'lesson_content_variants_hash_083') then
    alter table lesson_content_variants add constraint lesson_content_variants_hash_083
      check (source_lesson_hash ~ '^[0-9a-f]{64}$');
  end if;
  if not exists (select 1 from pg_constraint where conname = 'lesson_content_variants_choices_083') then
    alter table lesson_content_variants add constraint lesson_content_variants_choices_083
      check (jsonb_typeof(fade_choices) = 'array' and jsonb_typeof(solo_choices) = 'array');
  end if;
end $$;

-- Supabase Data API lock-out, as 026, 052, 060, 077, 078 and 079 did.
alter table lesson_content_variants enable row level security;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon')
     and exists (select 1 from pg_roles where rolname = 'authenticated') then
    revoke all on lesson_content_variants from anon, authenticated;
  end if;
end $$;

-- 2. The per-course switch (default off; nothing turns it on) ----------------------------

alter table subject_tracks add column if not exists beginner_variants boolean not null default false;

-- 3. Which version an answer was given to -------------------------------------------------

alter table attempts add column if not exists lesson_variant text;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'attempts_lesson_variant_083' and conrelid = 'attempts'::regclass) then
    alter table attempts add constraint attempts_lesson_variant_083
      check (lesson_variant is null or lesson_variant in ('new')) not valid;
  end if;
end $$;

-- 4. Holdbacks for a variant ---------------------------------------------------------------

-- FAIL-1720: restated under 067's own name, so 067's schema probe and a replay
-- of 067 or 079 keep seeing the check they expect.
do $$
declare
  c text;
  def text;
begin
  select pg_get_constraintdef(oid) into def from pg_constraint
   where conrelid = 'item_holdbacks'::regclass and conname = 'item_holdbacks_item_kind_067';
  if def is null or def not like '%''lesson_variant''%' then
    for c in select conname from pg_constraint
              where conrelid = 'item_holdbacks'::regclass and contype = 'c'
                and pg_get_constraintdef(oid) like '%item_kind%' loop
      execute format('alter table item_holdbacks drop constraint %I', c);
    end loop;
    alter table item_holdbacks add constraint item_holdbacks_item_kind_067 check (item_kind in
      ('lesson', 'lesson_intro', 'review', 'exam', 'quiz', 'comparison', 'pbq', 'unit_check', 'lab', 'sim', 'primer', 'lesson_variant')) not valid;
    alter table item_holdbacks validate constraint item_holdbacks_item_kind_067;
  end if;
end $$;

select app_runtime_sync();
